"""Brute-force solvers for Independent Set and Clique (for testing only)."""

from __future__ import annotations

from itertools import combinations


def _has_edges(n, edges, k, want_edge):
    """Return True if some k-subset has all pairs == want_edge."""
    if k <= 0:
        return True
    if k > n:
        return False
    adj = [[False] * n for _ in range(n)]
    for u, v in edges:
        adj[u][v] = adj[v][u] = True
    for subset in combinations(range(n), k):
        ok = True
        for i in range(k):
            for j in range(i + 1, k):
                if adj[subset[i]][subset[j]] != want_edge:
                    ok = False
                    break
            if not ok:
                break
        if ok:
            return True
    return False


def independent_set_solver(instance):
    return _has_edges(instance["n"], instance["edges"], instance["k"], False)


def clique_solver(instance):
    return _has_edges(instance["n"], instance["edges"], instance["k"], True)
EOF
